const records = $input.all().map(i => i.json);
return records.filter(r => String(r.active ?? '').trim().toLowerCase() === 'true' || r.active === true)
  .sort((a,b)=>Number(a.priority||99)-Number(b.priority||99))
  .slice(0,10)
  .filter(r=>/^https:\/\//i.test(String(r.feed_url||'')))
  .map(r=>({json:r}));

const responses = $input.all();
const radars = $('Filter Active Radars').all().map(x => x.json);
const windowStart = Date.now() - 48 * 60 * 60 * 1000;
const futureGrace = Date.now() + 15 * 60 * 1000;
const decode = v => String(v || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&#(x[0-9a-f]+|\d+);/gi, (_, c) => {
    const n = c[0].toLowerCase() === 'x' ? parseInt(c.slice(1), 16) : Number(c);
    return Number.isInteger(n) && n >= 0 && n <= 0x10ffff ? String.fromCodePoint(n) : '';
  })
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
  .replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const getTag = (xml, tag) => {
  const match = xml.match(new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  return match ? decode(match[1]) : '';
};
const result = [], seen = new Set();
let rejectedEvidenceItems = 0;
for (let i = 0; i < responses.length; i++) {
  const row = radars[i] || {}, response = responses[i].json || {};
  const xml = String(response.raw_feed || response.data || '');
  const items = [...xml.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)].slice(0, 25);
  let count = 0;
  for (const found of items) {
    // This is the literal observed RSS item, NOT reconstructed/normalized XML.
    const evidence = found[0];
    if (evidence.length > 500000) { rejectedEvidenceItems++; continue; }
    const item = found[1];
    const title = getTag(item, 'title'), link = getTag(item, 'link'), pub = getTag(item, 'pubDate');
    const t = Date.parse(pub);
    if (!title || !link || !Number.isFinite(t) || t < windowStart || t > futureGrace) continue;
    const key = (title + '|' + link).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push({
      radar: String(row.radar || ''), customer_segment_hint: String(row.customer_segment || ''),
      customer_job_hint: String(row.default_customer_job || ''), source_title: title,
      source_url: link, source_published_at: new Date(t).toISOString(),
      description: getTag(item, 'description').slice(0, 700),
      source_feed_url: String(row.feed_url || ''), source_feed_evidence: evidence,
    });
    count++; if (count >= 5) break;
  }
}
result.sort((a, b) => Date.parse(b.source_published_at) - Date.parse(a.source_published_at));
if (!result.length) return []; // No fresh usable evidence: no AI call or publication.
return [{json: {
  signals: result.slice(0, 40), totalSignals: result.length, checkedRadars: radars.length,
  rejectedEvidenceItems, generatedAt: new Date().toISOString(),
}}];

const xml = String($input.first()?.json?.rss || '');
const published = [];
const get = (s, t) => {
  const m = s.match(new RegExp('<' + t + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + t + '>', 'i'));
  return m?.[1]?.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim() || '';
};
for (const m of xml.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)) {
  published.push(get(m[1], 'title')); if (published.length >= 200) break;
}
const market = $('Collect Fresh News').first().json;
// Keep literal evidence internally. Sending raw RSS to Agnes wastes tokens and
// increases untrusted input; the model only needs the original short signals.
const promptSignals = (market.signals || []).map(({source_feed_evidence, source_feed_url, ...signal}) => signal);
const draftRules = [
  'ATURAN OUTPUT: Salin opportunity.source_title, source_url, source_published_at PERSIS dari satu sinyal RSS terpilih, termasuk suffix penerbit.',
  'Jangan mengarang fakta atau kutipan isi artikel asal; input hanya judul, deskripsi pendek, URL dan tanggal RSS. Berita menjadi sinyal ide; contoh angka harus ditandai sebagai ilustrasi.',
  'Kontrak API: title 20–100 karakter, excerpt 80–300, content Markdown minimal 500 kata dan 3 heading H2 ##, maksimal 120000 karakter, tags maksimal 8, FAQ maksimal 8 (question >=10 dan answer >=20 karakter).',
  'seo.metaDescription 70–170 karakter; metaTitle lebih dari 70 hanya peringatan SEO, bukan alasan memotong judul. Target editorial 900+ kata, 4–6 H2, 3 FAQ, metaTitle <=60, metaDescription 130–150 adalah rekomendasi, bukan syarat publikasi tambahan.',
  'Sertakan bagian Kesalahan yang sering terjadi bila relevan. Gunakan & biasa pada category. Jawab hanya JSON; bila tidak ada fit, qualified=false dan article=null.',
].join('\n');
const prompt = 'Waktu sekarang: ' + new Date().toISOString()
  + '\n\nSINYAL PASAR DARI RSS (bukan isi lengkap artikel):\n' + JSON.stringify(promptSignals)
  + '\n\nJUDUL BLOG EXISTING (hindari duplikasi):\n' + JSON.stringify(published)
  + '\n\nPilih satu pain paling actionable dengan VPC lengkap + skor. Buat satu artikel original problem-first.\n' + draftRules;
return [{json: {
  prompt, publishedTitles: published, marketSignals: market.signals || [], generatedAt: market.generatedAt,
}}];

const rules = {"title":[20,100],"excerpt":[80,300],"metaDescription":[70,170],"metaTitleMax":70,"minWords":500,"recommendedWords":900,"minH2":3,"maxTags":8,"maxFaq":8};
const res = $input.first().json;
const responseText = res?.choices?.[0]?.message?.content ?? res?.data?.choices?.[0]?.message?.content ?? res?.output_text;
const rejectResponse = reason => [{json: {
  qualified: false, opportunity: {}, article: null, totalScore: 0, sourceGrounded: false,
  duplicate: false, words: 0, h2: 0, generationStatus: 'invalid_response', reason,
}}];
if (typeof responseText !== 'string') return rejectResponse('Agnes response missing choices[0].message.content');
const finishReason = res?.choices?.[0]?.finish_reason ?? res?.data?.choices?.[0]?.finish_reason;
// Never try to salvage an incomplete model response. A real failed run had
// 547,519 trailing spaces: the old unanchored whitespace/fence regex retried at each space,
// monopolizing the runner's event loop until its heartbeat was lost.
if (finishReason === 'length') return rejectResponse('Agnes output TRUNCATED (finish_reason=length, chars=' + responseText.length + ').');
if (responseText.length > 200000) return rejectResponse('Agnes response exceeds safe parser size (chars=' + responseText.length + ').');
let jsonText = responseText.trim(); // linear; no backtracking over whitespace
if (jsonText.startsWith('\x60\x60\x60')) {
  const newline = jsonText.indexOf('\n');
  const fence = newline >= 0 ? jsonText.slice(0, newline).trim() : '';
  if (!['\x60\x60\x60', '\x60\x60\x60json'].includes(fence) || !jsonText.endsWith('\x60\x60\x60')) return rejectResponse('Agnes invalid JSON code fence');
  jsonText = jsonText.slice(newline + 1, -3).trim();
}
let parsed;
try { parsed = JSON.parse(jsonText); }
catch (e) {
  const fr = res?.choices?.[0]?.finish_reason || '';
  const trunc = fr === 'length' || /Unterminated|Unexpected end/i.test(e.message);
  return rejectResponse(trunc ? 'Agnes output TRUNCATED (finish_reason=' + fr + ', chars=' + responseText.length + ').' : 'Agnes invalid JSON: ' + e.message);
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return rejectResponse('Agnes output is not a JSON object');
if (typeof parsed.qualified !== 'boolean') return rejectResponse('Agnes qualified must be a boolean');
const op = parsed.opportunity && typeof parsed.opportunity === 'object' && !Array.isArray(parsed.opportunity) ? parsed.opportunity : {};
const market = $('Build VPC Prompt').first().json;
const sources = Array.isArray(market.marketSignals) ? market.marketSignals : [];
const match = sources.find(x => x.source_url === op.source_url && x.source_title === op.source_title && x.source_published_at === op.source_published_at);
const qualifiedByAI = parsed.qualified === true;
if (!qualifiedByAI) return [{json: {
  qualified: false, opportunity: op, article: null, totalScore: 0, sourceGrounded: false,
  duplicate: false, words: 0, h2: 0, generationStatus: 'no_fit', reason: String(op.reason || 'No suitable news this run'),
}}];
const parts = [['score_problem_relevance',25],['score_newhope_fit',25],['score_umkm_relevance',20],['score_business_impact',15],['score_content_potential',15]];
let score = 0;
for (const [k, max] of parts) {
  const v = Number(op[k]);
  if (!Number.isInteger(v) || v < 0 || v > max) return rejectResponse('Invalid score: ' + k);
  score += v;
}
if (score !== Number(op.total_score)) return rejectResponse('Inconsistent score total');
const a = parsed.article;
if (typeof a?.content === 'string' && a.content.length > 120000) return rejectResponse('Article content exceeds API size limit');
// Never trim the introduction, truncate headings or shorten a model's title to
// pass another contract. The publishing API is the canonical structural gate.
const cats = ['Tips Bisnis & Strategi','Panduan Kasir & POS','FinTech & QRIS','Kuliner & F&B','Laundry & Jasa','Ritel & Minimarket','Kisah Sukses UMKM'];
const normalizedText = v => typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : '';
const content = typeof a?.content === 'string' ? a.content : '';
const title = normalizedText(a?.title), excerpt = normalizedText(a?.excerpt);
const h2 = (content.match(/^##\s+/gm) || []).length;
const words = content.trim().split(/\s+/).filter(Boolean).length;
const faqOK = a?.faq === undefined || (Array.isArray(a.faq) && a.faq.length <= rules.maxFaq
  && a.faq.every(f => normalizedText(f?.question).length >= 10 && normalizedText(f?.answer).length >= 20));
const tagsOK = a?.tags === undefined || (Array.isArray(a.tags)
  && new Set(a.tags.map(normalizedText).filter(Boolean)).size <= rules.maxTags);
const meta = a?.seo && typeof a.seo === 'object' ? a.seo : {};
const metaDescription = normalizedText(meta.metaDescription);
// Absent metadata falls back to excerpt/title on the server; long metaTitle is
// a warning, not a blocker. Do not hide its warning by editing the article.
const seoOK = meta.metaDescription === undefined || meta.metaDescription === ''
  || (typeof meta.metaDescription === 'string' && metaDescription.length >= rules.metaDescription[0] && metaDescription.length <= rules.metaDescription[1]);
const basicOK = Boolean(a && typeof a === 'object' && !Array.isArray(a) && cats.includes(a.category)
  && title.length >= rules.title[0] && title.length <= rules.title[1]
  && excerpt.length >= rules.excerpt[0] && excerpt.length <= rules.excerpt[1]
  && typeof a.content === 'string' && content.length <= 120000 && words >= rules.minWords
  && h2 >= rules.minH2 && faqOK && tagsOK && seoOK);
const forbidden = [/tanpa\s+biaya\s+admin|mdr\s*0\s*%/i,/dijamin\s+(?:untung|laris|omzet|omset)|garansi\s+(?:omzet|omset|untung)/i,/lunas\s+otomatis/i,/pencairan\s+h\s*\+\s*1/i,/QRIS\s+dinamis/i];
const falseClaim = forbidden.some(p => p.test([a?.title, a?.excerpt, a?.content].join('\n')));
function tokens(str) {
  return new Set(String(str || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(s => s.length > 3 && !['untuk','yang','dengan','anda','dalam','agar','cara','bisnis'].includes(s)));
}
const aSet = tokens(a?.title);
const dup = (Array.isArray(market.publishedTitles) ? market.publishedTitles : []).some(t => {
  const b = tokens(t);
  if (!b.size || !aSet.size) return false;
  const intersection = [...aSet].filter(x => b.has(x)).length;
  return intersection / Math.min(b.size, aSet.size) >= 0.86 && intersection / Math.max(b.size, aSet.size) >= 0.65;
});
const sourceTime = match ? Date.parse(match.source_published_at) : NaN;
const stale = !Number.isFinite(sourceTime) || Date.now() - sourceTime > 48 * 3600000 || sourceTime > Date.now() + 15 * 60000;
const evidence = match?.source_feed_evidence;
const hasEvidence = typeof evidence === 'string' && evidence.length > 0 && evidence.length <= 500000
  && /<item\b[^>]*>[\s\S]*<\/item>/i.test(evidence);
const safe = qualifiedByAI && score >= 70 && !stale && hasEvidence && basicOK && !falseClaim && !dup;
if (a && typeof a === 'object' && !Array.isArray(a)) {
  a.sources = match ? [{title: match.source_title, url: match.source_url, publishedAt: match.source_published_at}] : [];
  a.sourceRequired = true;
  // Literal evidence only. Do not fabricate replacement XML for CDATA/attributes
  // that the API rejects; an API validation rejection must remain visible.
  a.sourceFeed = hasEvidence ? evidence : '';
}
return [{json: {
  qualified: Boolean(safe), opportunity: op, article: a ?? null, totalScore: score,
  sourceGrounded: Boolean(match && hasEvidence), duplicate: dup, words, h2,
  generationStatus: safe ? 'qualified' : dup ? 'duplicate' : 'rejected_quality',
  reason: safe ? '' : JSON.stringify({stale, hasEvidence, basicOK, falseClaim, dup, score, words, h2, faqOK, tagsOK, seoOK,
    metaTitleLength: normalizedText(meta.metaTitle).length, metaDescriptionLength: metaDescription.length}),
}}];

const src=$('Parse Agnes - Validate VPC').first().json;
const r=$input.first().json;
const status=Number(r.statusCode||r.status||0),body=r.body||{};
const published=status>=200&&status<300&&body?.ok===true&&body?.post?.isPublished===true&&Boolean(body?.post?.url);
const error=status===422?'error_422':status===409?'error_409':status===401?'error_401':published?'published':'error_http';
const o=src.opportunity||{};
const row={discovered_at:new Date().toISOString(),source_title:o.source_title||'',source_url:o.source_url||'',source_published_at:o.source_published_at||'',radar:o.radar||'',customer_segment:o.customer_segment||'',customer_job:o.customer_job||'',pain:o.pain||'',business_impact:o.business_impact||'',desired_gain:o.desired_gain||'',newhope_capability:o.newhope_capability||'',pain_reliever:o.pain_reliever||'',gain_creator:o.gain_creator||'',score_problem_relevance:o.score_problem_relevance||0,score_newhope_fit:o.score_newhope_fit||0,score_umkm_relevance:o.score_umkm_relevance||0,score_business_impact:o.score_business_impact||0,score_content_potential:o.score_content_potential||0,total_score:o.total_score||0,content_angle:o.content_angle||'',focus_keyword:o.focus_keyword||'',category:o.category||'',status:error,blog_url:published?(body?.post?.url||body?.data?.post?.url||''):'',reason:published?(o.reason||''):(JSON.stringify(body?.details?.errors||body?.error||body).slice(0,1800)),raw_analysis:JSON.stringify(o)};
return [{json:row}];

const src = $('Parse Agnes - Validate VPC').first().json;
const result = $input.first().json;
const qualityStatuses = ['no_fit', 'invalid_response', 'duplicate', 'rejected_quality'];
const isQualityDecision = result.qualified === false && qualityStatuses.includes(result.generationStatus);
const httpStatus = Number(result.statusCode || 0), body = result.body || {};
const o = src.opportunity || {};
const status = isQualityDecision ? result.generationStatus
  : httpStatus === 401 ? 'error_401' : httpStatus === 422 ? 'error_422'
  : httpStatus >= 500 ? 'error_5xx' : body.ok === false ? 'validation_rejected' : 'error_http';
const reason = isQualityDecision ? String(result.reason || 'Generation rejected before publication')
  : JSON.stringify(body?.details?.errors || body?.errors || body?.error || body || {status: httpStatus});
return [{json: {
  discovered_at: new Date().toISOString(), source_title: o.source_title || '', source_url: o.source_url || '',
  source_published_at: o.source_published_at || '', radar: o.radar || '', customer_segment: o.customer_segment || '',
  customer_job: o.customer_job || '', pain: o.pain || '', business_impact: o.business_impact || '', desired_gain: o.desired_gain || '',
  newhope_capability: o.newhope_capability || '', pain_reliever: o.pain_reliever || '', gain_creator: o.gain_creator || '',
  score_problem_relevance: o.score_problem_relevance || 0, score_newhope_fit: o.score_newhope_fit || 0,
  score_umkm_relevance: o.score_umkm_relevance || 0, score_business_impact: o.score_business_impact || 0,
  score_content_potential: o.score_content_potential || 0, total_score: o.total_score || 0,
  content_angle: o.content_angle || '', focus_keyword: o.focus_keyword || '', category: o.category || '',
  status, blog_url: '', reason: reason.slice(0, 1800), raw_analysis: JSON.stringify(o),
}}];

const src = $('Parse Agnes - Validate VPC').first().json;
const o = src.opportunity || {};
return [{json: {
  discovered_at: new Date().toISOString(), source_title: o.source_title || '', source_url: o.source_url || '',
