// User authorized live blog execution on 2026-10-09; Make stays on a separate weekly schedule.
// Keep the existing API validation, source, freshness, claim and duplicate gates.
const LIVE_PUBLISH_ENABLED = true;
return $input.all().map(item => ({json: {...item.json, publishEnabled: LIVE_PUBLISH_ENABLED}}));

const palettes = ['terracotta and cream','sage green and warm ivory','navy and pale peach','mustard and deep brown','teal and sand','burgundy and pearl'];
const scenes = ['overhead still life with ingredients arranged by unit cost and a kitchen scale','a small Indonesian food stall owner evaluating portions in a bright preparation kitchen','a boutique shop owner reviewing a simple visual sales chart among neatly arranged merchandise','a close-up of receipts grouped into three separate reconciliation trays','a split composition contrasting full order baskets with a small remaining profit jar','a ceramic plate with layered ingredient portions beside a measuring scoop','an isometric miniature shop with transparent blocks showing money flowing into cost categories','a bakery owner comparing two batches of bread and their ingredient baskets'];
return $input.all().map((item,index)=>{
 const repair=item.json.mode==='repair';
 const a=repair?item.json.article:$('Parse Agnes - Validate VPC').first().json.article;
 if(!a?.title||!a?.excerpt)throw Error('Cover job lacks article context');
 const hash=Array.from(a.slug||a.title).reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0);
 const title=a.title.toLowerCase();
 const cashScenes=['three distinct receipt trays being reconciled in a small shop at closing time','a shop owner comparing abstract payment records with a ledger on a bright wooden desk','three colored payment streams converging into a balanced reconciliation scale','an isometric shop with separate cash, contactless and bank-transfer lanes being matched'];
 const costScenes=['a chef weighing ingredients for a single plated meal in a clean preparation kitchen','an overhead arrangement of portioned Indonesian ingredients beside a kitchen scale','a bakery owner checking flour and butter quantities beside freshly baked bread','a market vendor measuring raw ingredients beside carefully portioned meal bowls'];
 const profitScenes=['a boutique owner comparing a full order basket against a small remaining profit jar','a miniature shop with transparent cost blocks and a visible remaining margin','a balancing scale comparing retail inventory costs with a symbolic sales basket','an overhead still life of product samples and grouped cost receipts'];
 const relevant=/rekonsiliasi|qris|tunai|transfer|selisih kas/.test(title)?cashScenes:/hpp|bahan|porsi|menu|f&b/.test(title)?costScenes:profitScenes;
 const scene=relevant[hash%relevant.length], palette=palettes[Math.floor(hash/relevant.length)%palettes.length];
 const prompt='Create a polished editorial illustration for an Indonesian small-business article. Topic: '+a.title+'. Context: '+a.excerpt+'. Interpret the specific topic faithfully using this distinct visual starting point: '+scene+'. Palette: '+palette+'. Warm natural light, tactile materials, sophisticated magazine art direction, clear focal subject, wide 16:9 composition, full bleed, no border. No headline, no captions, no legible numbers, no logos, no watermark. Avoid the generic cash-register/phone/banknotes-on-a-cafe-counter scene. This is a conceptual illustration, not a photograph of the event in the news. Each article needs its own visual interpretation.';
 return {json:{mode:repair?'repair':'publish',article:a,expectedCover:repair?item.json.expectedCover:undefined,prompt,alt:('Ilustrasi AI: '+a.title).slice(0,160)},pairedItem:{item:index}};
});
